// Work out how many photo cards fit across the screen, and how wide each one is.
function gridLayout(screenWidth, { minCardWidth = 160, gap = 12, padding = 16 } = {}) {
  const columns = Math.floor(screenWidth / minCardWidth);
  const cardWidth = screenWidth / columns;
  return { columns, cardWidth };
}

console.log(gridLayout(390)); // iPhone in portrait
console.log(gridLayout(820)); // iPad in portrait

